set -euo pipefail

if [[ -n "${SEMREL_CONTRIBUTORS:-}" ]]; then
  export SEMREL_PLUGIN_CONTRIBUTORS_JSON="$(
    python3 -c '
import json
import sys

contributors = json.load(sys.stdin)
if not isinstance(contributors, list):
    raise SystemExit("SEMREL_CONTRIBUTORS must be a JSON array")
print(json.dumps([
    {"name": contributor["name"]}
    for contributor in contributors
    if contributor.get("firstContribution") is True and contributor.get("name")
], separators=(",", ":")))
' <<<"${SEMREL_CONTRIBUTORS}"
  )"
fi

exec "${PWD}/.semrel/plugins/semrel-plugin-release-notes"
